const r = await tools.exec_command({
  cmd: ".venv/bin/python - <<'PY'
import duckdb
c=duckdb.connect('/tmp/lion-phase2-run1.duckdb',read_only=True)
queries={
'base_events':"select count(*) raw_rows,count(distinct order_id) orders,count(distinct order_id) filter(where n>1) multi_orders from (select *,count(*) over(partition by order_id)n from staging.order_event)",
'canonical_conflicts':"select (select sum(duplicate_source_row_count-1) from staging.order_event where is_canonical_event) exact_duplicate_extras,(select count(*) from (select order_id,updated_at from staging.order_event where is_canonical_event group by 1,2 having count(distinct canonical_event_hash)>1)) same_timestamp_conflicts,(select count(*) from (select order_id from staging.order_event where is_canonical_event group by 1 having count(distinct invariant_hash)>1)) invariant_conflicts,(select count(*) from (select order_id from staging.order_event where is_canonical_event qualify rank() over(partition by order_id order by updated_at desc)=1 group by order_id having count(*)>1)) latest_ties",
'quarantine_combos':"select string_agg(rule_id,',' order by rule_id) rules,count(*) entities from quality.entity_rule where entity_type='order' and disposition='QUARANTINE' group by business_key order by rules",
'unknown_members':"select count(*) rows,count(distinct member_id) members,min(order_created_at),max(order_created_at) from curated.fact_order where member_sk=0",
'member_presence':"select count(distinct member_id) source_members,(select count(distinct member_id) from curated.dim_member where not is_unknown) represented,(select count(*) from (select member_id from curated.dim_member where not is_unknown group by 1 having sum(is_current::int)=0)) no_current",
'money_by_currency':"select normalized_currency,count(*) rows,sum(gross_amount_twd_exact) gross_exact,sum(net_amount_twd_exact) net_exact from curated.fact_order group by 1 order by 1"
}
for n,q in queries.items():
 print(n,c.execute(q).fetchall())
PY",
