'quarantine_combos':"""with x as(select business_key,string_agg(rule_id,',' order by rule_id) rules from quality.entity_rule where entity_type='order' and disposition='QUARANTINE' group by business_key) select rules,count(*) entities from x group by rules order by rules""",
